pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address currentOwner, address newOwner, address nonOwner) public {
        vm.assume(currentOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(nonOwner != address(0));
        vm.assume(currentOwner != nonOwner);

        vm.prank(address(c).balance > 0 ? address(this) : address(this));
        c.transferOwnership(currentOwner);

        vm.prank(nonOwner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));

        assertTrue(!success);
    }
}
